SELECT CAST(COUNT(CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM a.dischtime) BETWEEN 2015 AND 2016 AND a.dischtime - a.admittime >= 7 AND (a.discharge_location = 'home' OR a.discharge_location IN ('SNF', 'rehab', 'LTACH') OR a.deathtime IS NOT NULL) THEN 1 END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.anchor_age = 69 AND p.gender = 'M' AND EXTRACT(YEAR FROM a.dischtime) BETWEEN 2015 AND 2016 AND (a.discharge_location = 'home' OR a.discharge_location IN ('SNF', 'rehab', 'LTACH') OR a.deathtime IS NOT NULL);